<?php declare(strict_types=1); namespace App\Infrastructure\Persistence\Doctrine\Review; use App\Domain\Review\Entity\NotebookAnalysisAction;use App\Domain\Review\Enum\NotebookAnalysisActionType;use App\Domain\Review\Repository\NotebookAnalysisActionRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Review\Entity\NotebookAnalysisActionRecord;use Doctrine\ORM\EntityManagerInterface; final class DoctrineNotebookAnalysisActionRepository implements NotebookAnalysisActionRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function save(NotebookAnalysisAction $a):void{$r=new NotebookAnalysisActionRecord();foreach(['id','executionId','questionId','taxonomySubjectId','flashcardId','reason','payload','appliedAt','createdAt'] as $p)$r->$p=$a->$p;$r->type=$a->type->value;$r->confidence=(string)$a->confidence;$this->em->persist($r);} public function listForExecution(string $e):array{$rs=$this->em->getRepository(NotebookAnalysisActionRecord::class)->findBy(['executionId'=>$e],['createdAt'=>'ASC']);return array_map(fn(NotebookAnalysisActionRecord $r)=>new NotebookAnalysisAction($r->id,$r->executionId,$r->questionId,$r->taxonomySubjectId,$r->flashcardId,NotebookAnalysisActionType::from($r->type),$r->reason,(float)$r->confidence,$r->payload,$r->appliedAt,$r->createdAt),$rs);} }
